//! Checkpoint 1, technique tests: is the library correct for the right
//! reasons?
//!
//! Run: cargo test --test technique
//!
//! These tests look at how the code works: what it borrows, what it copies,
//! how wide its arithmetic is, and whether a failed operation leaves anything
//! behind. All of them must pass, in debug and with `--release`, for the
//! "proficient" level in RUBRIC.md. Do not edit this file.

mod common;

use common::{is_slice_of, measure, within};
use splitpot::{Entry, Ledger, Overflow, Transfer, Unbalanced, parse_amount, parse_entry, settle};

fn owned(pairs: &[(&str, i64)]) -> Vec<(String, i64)> {
    pairs
        .iter()
        .map(|&(name, cents)| (name.to_string(), cents))
        .collect()
}

// --------------------------------------------------------------- borrowing

#[test]
fn entry_names_are_slices_of_the_line() {
    let line = String::from("  Zoë paid 4.20 for  李 , Zoë,ben  ");
    let entry = parse_entry(&line).unwrap();
    assert!(
        is_slice_of(entry.payer, &line),
        "`payer` must borrow from the line, not point to a copy of the name"
    );
    assert_eq!(
        entry.payer.as_ptr() as usize - line.as_ptr() as usize,
        2,
        "`payer` must start at the first character of the line that is not white space"
    );
    for name in &entry.sharers {
        assert!(
            is_slice_of(name, &line),
            "sharer {name:?} must borrow from the line, not point to a copy of the name"
        );
    }
    let second = line.rfind("Zoë").unwrap();
    assert_eq!(
        entry.sharers[1].as_ptr() as usize - line.as_ptr() as usize,
        second,
        "the sharer Zoë is the second occurrence in the line, not the payer's slice again"
    );
}

#[test]
fn entries_can_outlive_the_loop_that_reads_them() {
    // This compiles only because an `Entry` borrows from the text and from
    // nothing shorter-lived, such as a temporary line buffer.
    let text = String::from("a paid 1 for b\nb paid 2 for a, c\n");
    let mut entries: Vec<Entry<'_>> = Vec::new();
    for line in text.lines() {
        entries.push(parse_entry(line).unwrap());
    }
    assert_eq!(entries.len(), 2);
    assert!(is_slice_of(entries[1].sharers[1], &text));
}

// -------------------------------------------------------------- allocation

#[test]
fn parse_amount_never_allocates() {
    let texts = [
        "12.50",
        "184467440737095516.15",
        "",
        "5.123",
        "99999999999999999999999999",
        "+5",
    ];
    for text in texts {
        let (_, heap) = measure(|| parse_amount(text));
        assert_eq!(
            heap.calls, 0,
            "parse_amount({text:?}) allocated {} time(s); digits can be read in place",
            heap.calls
        );
    }
}

#[test]
fn parse_entry_allocates_only_the_list_of_sharers() {
    let line = "ana   paid 30.00 for ana, ben ,cy";
    let (entry, heap) = measure(|| parse_entry(line));
    assert_eq!(entry.unwrap().sharers.len(), 3);
    assert!(
        heap.calls <= 1,
        "parse_entry allocated {} times for three sharers; the budget is 1, the `Vec` of \
         sharers. Do not collect the words of the line into a temporary list, and do not \
         build a changed copy of the line.",
        heap.calls
    );
}

#[test]
fn rejected_lines_cost_no_allocation() {
    for line in [
        "",
        "ana",
        "ana paid",
        "ana paid x for ben",
        "ana gave 5 for ben",
        "ana paid 5 to ben",
    ] {
        let (result, heap) = measure(|| parse_entry(line));
        assert!(result.is_err());
        assert_eq!(
            heap.calls, 0,
            "parse_entry({line:?}) allocated {} time(s) although the error is in front of the \
             list of sharers",
            heap.calls
        );
    }
}

#[test]
fn looking_up_a_balance_does_not_allocate() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 30 for ana, ben, cy").unwrap())
        .unwrap();
    let ((known, unknown), heap) = measure(|| (ledger.balance("ben"), ledger.balance("nobody")));
    assert_eq!((known, unknown), (Some(-1000), None));
    assert_eq!(
        heap.calls, 0,
        "`balance` must compare names in place, not build a String to compare"
    );
}

#[test]
fn add_does_not_copy_the_ledger() {
    // 60 people.
    let names: Vec<String> = (0..60).map(|i| format!("person{i:02}")).collect();
    let mut ledger = Ledger::new();
    for pair in names.chunks(2) {
        let entry = Entry {
            payer: &pair[0],
            cents: 100,
            sharers: vec![pair[1].as_str()],
        };
        ledger.add(&entry).unwrap();
    }
    let sharers = vec![names[7].as_str(), names[20].as_str(), names[41].as_str()];
    let entry = Entry {
        payer: &names[7],
        cents: 999,
        sharers,
    };
    let (result, heap) = measure(|| ledger.add(&entry));
    assert_eq!(result, Ok(()));
    assert!(
        heap.calls <= 4,
        "adding an entry for people who are already in the ledger allocated {} times. \
         Keeping a backup copy of the whole ledger is not needed to make `add` safe: \
         check everything first, then write.",
        heap.calls
    );
}

// --------------------------------------------------------------- ownership

#[test]
fn into_balances_moves_the_names() {
    let mut ledger = Ledger::new();
    for line in [
        "hanna-the-treasurer paid 80 for gustav-the-driver, frida-the-cook, emil-the-navigator",
        "dora-the-photographer paid 12 for carl-the-musician, berit-the-planner, axel-the-latecomer",
    ] {
        ledger.add(&parse_entry(line).unwrap()).unwrap();
    }
    let before: Vec<*const u8> = ledger.names().iter().map(|name| name.as_ptr()).collect();
    assert_eq!(before.len(), 8);

    let (balances, heap) = measure(|| ledger.into_balances());
    let after: Vec<*const u8> = balances.iter().map(|(name, _)| name.as_ptr()).collect();
    assert_eq!(
        before, after,
        "into_balances must hand over the same String buffers that the ledger owned, not copies"
    );
    assert!(
        heap.calls <= 2,
        "into_balances allocated {} times for 8 people; it owns the names and can move them",
        heap.calls
    );
}

// ------------------------------------------------------------- atomic add

#[test]
fn failed_add_does_not_credit_the_payer() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 92233720368547758.07 for ben").unwrap())
        .unwrap();
    // ben: -i64::MAX. One more cent of debt still fits: i64::MIN.
    ledger
        .add(&parse_entry("cy paid 0.02 for cy, ben").unwrap())
        .unwrap();
    assert_eq!(ledger.balance("ben"), Some(i64::MIN));
    assert_eq!(ledger.balance("cy"), Some(1));

    let again = parse_entry("cy paid 0.02 for cy, ben").unwrap();
    assert_eq!(ledger.add(&again), Err(Overflow));
    assert_eq!(
        ledger.balance("cy"),
        Some(1),
        "the entry failed because of ben, so cy's balance must be untouched as well"
    );
    assert_eq!(ledger.balance("ben"), Some(i64::MIN));
    assert_eq!(ledger.balance("ana"), Some(i64::MAX));
}

#[test]
fn failed_add_does_not_introduce_new_people() {
    let mut ledger = Ledger::new();
    ledger
        .add(&parse_entry("ana paid 92233720368547758.07 for ben").unwrap())
        .unwrap();
    ledger
        .add(&parse_entry("cy paid 0.01 for ben").unwrap())
        .unwrap();
    assert_eq!(ledger.balance("ben"), Some(i64::MIN));

    for line in [
        "dee paid 0.03 for dee, eve, ben",
        "dee paid 0.03 for ben, eve, dee",
        "ben paid 0.00 for eve",
        "eve paid 0.03 for dee, ben",
    ] {
        let entry = parse_entry(line).unwrap();
        let result = ledger.add(&entry);
        if line.starts_with("ben paid 0.00") {
            assert_eq!(
                result,
                Ok(()),
                "{line:?} changes no balance and must succeed"
            );
            assert_eq!(ledger.balance("eve"), Some(0));
            continue;
        }
        assert_eq!(
            result,
            Err(Overflow),
            "{line:?} would push ben below i64::MIN"
        );
        assert_eq!(
            ledger.balance("dee"),
            None,
            "after the failed {line:?}, dee must not be in the ledger at all"
        );
    }
    assert_eq!(ledger.names(), ["ana", "ben", "cy", "eve"]);
    assert_eq!(
        ledger.balance("eve"),
        Some(0),
        "the failed entries must not have charged eve"
    );
}

// ------------------------------------------------------------ wide numbers

#[test]
fn credit_and_own_share_are_combined_before_the_range_check() {
    // u64::MAX cents do not fit in an i64, but ana owes the whole amount to
    // herself, so her balance does not change at all.
    let mut ledger = Ledger::new();
    let entry = parse_entry("ana paid 184467440737095516.15 for ana").unwrap();
    assert_eq!(
        ledger.add(&entry),
        Ok(()),
        "the change of a person is credit minus own share; only the resulting balance must fit in an i64"
    );
    assert_eq!(ledger.balance("ana"), Some(0));

    // u64::MAX = 2 * i64::MAX + 1. ana takes the extra cent.
    let mut ledger = Ledger::new();
    let entry = parse_entry("ana paid 184467440737095516.15 for ana, ben").unwrap();
    assert_eq!(ledger.add(&entry), Ok(()));
    assert_eq!(ledger.balance("ana"), Some(i64::MAX));
    assert_eq!(ledger.balance("ben"), Some(-i64::MAX));

    // The same entry with ben first: ben takes the extra cent.
    let mut ledger = Ledger::new();
    let entry = parse_entry("ana paid 184467440737095516.15 for ben, ana").unwrap();
    assert_eq!(
        ledger.add(&entry),
        Err(Overflow),
        "ana would be owed i64::MAX + 1"
    );
    assert!(ledger.names().is_empty());
}

#[test]
fn settle_handles_a_debt_of_i64_min() {
    // The sum is exactly zero, but -i64::MIN does not exist as an i64.
    let balances = owned(&[("deep", i64::MIN), ("rich", i64::MAX), ("tip", 1)]);
    let plan = within(10, "settle", move || {
        settle(&balances).map(|plan| {
            plan.iter()
                .map(|t| (t.from.to_string(), t.to.to_string(), t.cents))
                .collect::<Vec<_>>()
        })
    });
    assert_eq!(
        plan,
        Ok(vec![
            ("deep".to_string(), "rich".to_string(), i64::MAX as u64),
            ("deep".to_string(), "tip".to_string(), 1),
        ])
    );
}

#[test]
fn settle_checks_the_exact_sum() {
    // In an i64, MIN + MIN wraps around to exactly 0, and MAX + MAX + 2 does too.
    for pairs in [
        vec![("a", i64::MIN), ("b", i64::MIN)],
        vec![("a", i64::MAX), ("b", i64::MAX), ("c", 2)],
        vec![("a", i64::MAX), ("b", i64::MAX)],
        vec![("a", i64::MAX), ("b", 1)],
    ] {
        let balances = owned(&pairs);
        let result = within(10, "settle", move || {
            settle(&balances).map(|plan| plan.len())
        });
        assert_eq!(
            result,
            Err(Unbalanced),
            "{pairs:?} do not add up to zero; add them in a type that cannot overflow"
        );
    }
}

#[test]
fn transfers_borrow_the_names_of_the_balances() {
    let balances = owned(&[("ana", 700), ("ben", -400), ("cy", -300)]);
    let plan: Vec<Transfer<'_>> = settle(&balances).unwrap();
    assert_eq!(plan.len(), 2);
    for t in &plan {
        for name in [t.from, t.to] {
            assert!(
                balances
                    .iter()
                    .any(|(owner, _)| std::ptr::eq(owner.as_str(), name)),
                "the name {name:?} in a transfer must be the same string as in `balances`, not a copy"
            );
        }
    }
}
